struct Ship {
    name,
    fuel,
}

impl Ship {
    fn fly(self, distance) {
        if distance > self.fuel {
            return Err(`${self.name} is out of fuel`);
        }

        self.fuel -= distance;
        Ok(self.fuel)
    }
}

pub fn main() {
    let ship = Ship { name: "Rocinante", fuel: 100 };

    let left = ship.fly(60)?;
    println!("{} has {} fuel left", ship.name, left);

    ship.fly(60)
}

enum Shape {
    Circle(r),
    Rect { w, h },
}

fn describe(shape) {
    match shape {
        Shape::Circle(r) => `a circle with area ${3.14 * r * r}`,
        Shape::Rect { w, h } if w == h => `a square with area ${w * h}`,
        Shape::Rect { w, h } => `a ${w} by ${h} rectangle`,
    }
}

pub fn main() {
    let shapes = [
        Shape::Circle(2.0),
        Shape::Rect { w: 3, h: 3 },
        Shape::Rect { w: 2, h: 5 },
    ];

    for shape in shapes {
        println!("{}", describe(shape));
    }
}

fn fibonacci() {
    let a = 0;
    let b = 1;

    loop {
        yield a;
        let next = a + b;
        a = b;
        b = next;
    }
}

pub fn main() {
    let evens = [];

    for n in fibonacci() {
        if n > 1000 {
            break;
        }

        if n % 2 == 0 {
            evens.push(n);
        }
    }

    evens
}

