use std::future;

async fn fetch(name, steps) {
    let total = 0;

    for n in 0..steps {
        total += n;
    }

    `${name}: ${total}`
}

pub async fn main() {
    let (a, b) = future::join((fetch("users", 100), fetch("posts", 10))).await;
    println!("{a}, {b}");

    let first = select {
        value = fetch("cache", 1) => value,
        value = fetch("database", 1000) => value,
    };

    first
}

