const PRIMES = {
    let primes = [];
    let n = 2;

    while primes.len() < 10 {
        let prime = true;

        for p in primes {
            if n % p == 0 {
                prime = false;
                break;
            }
        }

        if prime {
            primes.push(n);
        }

        n += 1;
    }

    primes
};

pub fn main() {
    println!("Computed once, at compile time:");
    PRIMES
}

